package br.edu.vendas.converter;
import br.edu.vendas.model.Categoria; import br.edu.vendas.service.CategoriaService; import jakarta.faces.component.UIComponent; import jakarta.faces.context.FacesContext; import jakarta.faces.convert.Converter; import jakarta.faces.convert.FacesConverter; import jakarta.inject.Inject;
@FacesConverter(value="categoriaConverter",managed=true) public class CategoriaConverter implements Converter<Categoria>{ @Inject CategoriaService service; public Categoria getAsObject(FacesContext c,UIComponent u,String v){if(v==null||v.isBlank())return null;return service.listar().stream().filter(x->String.valueOf(x.getId()).equals(v)).findFirst().orElse(null);} public String getAsString(FacesContext c,UIComponent u,Categoria v){return v==null||v.getId()==null?"":v.getId().toString();}}
